selector .elementor-button {
  background: linear-gradient(117deg, rgba(223, 54, 136, 1) 0%, rgba(247, 151, 198, 1) 55%, rgba(223, 54, 136, 1) 100%);
  background-size: 200% 200%;

  box-shadow: inset 0 0 8px rgba(255, 255, 255, 0.8) !important;

  animation: gradienteMove 4s ease infinite;
}

@keyframes gradienteMove {
  0% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
  100% {
    background-position: 0% 50%;
  }
}

selector .elementor-button svg{
    width: 30px; /*altere o tamanho aqui*/
    height: 30px; /*altere o tamanho aqui*/
    vertical-align: middle;
}

selector .elementor-button-content-wrapper {
    align-items: center
}

.borda-animada {
  position: relative;
  border-radius: 20px;
  z-index: 1;
}

/* Borda animada */
.borda-animada::before {
  content: "";
  position: absolute;
  inset: -2px; /* espessura da borda */
  border-radius: inherit;

  background: linear-gradient(
    120deg,
    transparent,
    #DF3688,
    transparent,
    #DF3688
  );

  background-size: 300% 300%;
  animation: bordaAnimada 3s linear infinite;

  z-index: -1;
}

/* Recorte interno (pra virar “borda” de verdade) */
.borda-animada2::after {
  content: "";
  position: absolute;
  inset: 1px;
  background: #000; /* ou transparent, ou a cor do seu fundo */
  border-radius: inherit;
  z-index: -1;
}

/* Animação */
@keyframes bordaAnimada {
  0% {
    background-position: 0% 50%;
  }
  100% {
    background-position: 200% 50%;
  }
}

