.myPricing{
    --text: 'ASSINATURA MENSAL';
    --first-color: #DF3688;
    --second-color: #FFFFFF;
    
    position: relative;
}
.myPricing .myRibbon{
    position: absolute;
    top: -10px;
    right: -10px;
    width: 180px;            /* ↑ antes 150px */
    height: 180px;           /* ↑ antes 150px */
    display: flex;
    justify-content: center;
    align-items: center;
    overflow: hidden;
}
.myPricing .myRibbon::before{
    content: var(--text);
    position: absolute;
    width: 160%;             /* ↑ antes 150%  – faixa mais comprida */
    height: 50px;            /* ↑ antes 40px – faixa mais alta */
    background: var(--first-color);
    transform: rotate(45deg) translateY(-20px);
    display: flex;
    justify-content: center;
    align-items: center;
    font-size: 16px;         /* ↑ antes 15px */
    font-weight: 600;
    color: #fff;
    letter-spacing: 0.05em;
    box-shadow: 0 5px 10px rgba(0,0,0,0.1);
    font-family: poppins;
}
.myPricing .myRibbon::after{
    content: '';
    position: absolute;
    bottom: 0;
    right: 0;
    width: 0px;
    height: 0px;
    background: var(--second-color);
    z-index: -1;
    box-shadow: -160px -160px var(--second-color); /* acompanha o novo tamanho */
}

